/* Palette: dark background, cream card, accent teal, muted coral, soft gray */
:root {
  --bg: #1e2a3a;
  --card-bg: #f5f0e8;
  --text: #1e2a3a;
  --accent: #2a9d8f;
  --accent-hover: #21867a;
  --accent-active: #1a6b61;
  --danger: #e76f51;
  --danger-hover: #d15b3e;
  --danger-active: #b84a30;
  --muted: #6b7a8f;
  --border: #d4cfc4;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 24px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 2px solid var(--border);
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-weight: 500;
  user-select: none;
}

.filter-label input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
  cursor: pointer;
}

.count {
  font-weight: 600;
  color: var(--muted);
  margin-left: auto;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  padding: 12px 16px;
  background: #fff;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.book-title {
  font-weight: 500;
  flex: 1 1 180px;
}

.book-status {
  font-size: 0.85rem;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  white-space: nowrap;
}

.book-status.available {
  background: #d1f0eb;
  color: #1a6b61;
}

.book-status.checked-out {
  background: #fde2dc;
  color: #b84a30;
}

.btn {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 8px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn-checkout {
  background: var(--accent);
  color: #fff;
}

.btn-checkout:hover {
  background: var(--accent-hover);
}

.btn-checkout:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

.btn-return {
  background: var(--danger);
  color: #fff;
}

.btn-return:hover {
  background: var(--danger-hover);
}

.btn-return:active {
  background: var(--danger-active);
  transform: scale(0.97);
}

.empty-message {
  text-align: center;
  color: var(--muted);
  padding: 24px 0;
  font-style: italic;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .book-item {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  .book-title {
    flex: none;
  }
  .count {
    margin-left: 0;
  }
}

const books = [
  { id: 1, title: 'The Pixel Art Handbook', checkedOut: false },
  { id: 2, title: 'JavaScript: The Good Parts', checkedOut: false },
  { id: 3, title: 'CSS Secrets', checkedOut: true },
  { id: 4, title: 'Design Systems', checkedOut: false },
  { id: 5, title: 'Eloquent JavaScript', checkedOut: true },
  { id: 6, title: 'Refactoring UI', checkedOut: false }
];

const bookList = document.getElementById('bookList');
const filterCheckbox = document.getElementById('filterAvailable');
const countDisplay = document.getElementById('checkedOutCount');

function render() {
  const filterAvailable = filterCheckbox.checked;
  const visibleBooks = filterAvailable ? books.filter(b => !b.checkedOut) : books;

  bookList.innerHTML = '';

  if (visibleBooks.length === 0) {
    const empty = document.createElement('li');
    empty.className = 'empty-message';
    empty.textContent = 'No available books match the filter.';
    bookList.appendChild(empty);
  } else {
    visibleBooks.forEach(book => {
      const li = document.createElement('li');
      li.className = 'book-item';

      const titleSpan = document.createElement('span');
      titleSpan.className = 'book-title';
      titleSpan.textContent = book.title;

      const statusSpan = document.createElement('span');
      statusSpan.className = 'book-status ' + (book.checkedOut ? 'checked-out' : 'available');
      statusSpan.textContent = book.checkedOut ? 'Checked out' : 'Available';

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'btn ' + (book.checkedOut ? 'btn-return' : 'btn-checkout');
      btn.textContent = book.checkedOut ? 'Return' : 'Check out';
      btn.setAttribute('aria-label', (book.checkedOut ? 'Return ' : 'Check out ') + book.title);
      btn.addEventListener('click', () => toggleBook(book.id));

      li.appendChild(titleSpan);
      li.appendChild(statusSpan);
      li.appendChild(btn);
      bookList.appendChild(li);
    });
  }

  const checkedOutCount = books.filter(b => b.checkedOut).length;
  countDisplay.textContent = 'Checked out: ' + checkedOutCount;
}

function toggleBook(id) {
  const book = books.find(b => b.id === id);
  if (book) {
    book.checkedOut = !book.checkedOut;
    render();
  }
}

filterCheckbox.addEventListener('change', render);

render();
